package com.app.controller; import com.app.dto.SocietyComplaintDtos.*; import com.app.security.UserPrincipal; import com.app.service.SocietyComplaintService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/society/complaints") @RequiredArgsConstructor public class SocietyComplaintController {private final SocietyComplaintService service;@GetMapping public List<ComplaintDto> list(@AuthenticationPrincipal UserPrincipal p){return service.list(p.getAccountId(),p.getUserId());}@GetMapping("/{id}") public ComplaintDto get(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){return service.get(p.getAccountId(),p.getUserId(),id);}@PostMapping public ComplaintDto create(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody CreateRequest r){return service.create(p.getAccountId(),p.getUserId(),r);}@PostMapping("/{id}/updates") public ComplaintDto update(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id,@Valid @RequestBody UpdateRequest r){return service.update(p.getAccountId(),p.getUserId(),id,r);}@PostMapping("/{id}/work-order") public ComplaintDto convert(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id,@Valid @RequestBody ConvertRequest r){return service.convert(p.getAccountId(),p.getUserId(),id,r);}}
